#version 300 es
precision highp float;
uniform vec2 uResolution;
uniform float uTime;
uniform vec2 uMouse;
uniform float uBreath;
out vec4 fragColor;

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}
float hash21(vec2 p) {
    p = fract(p * vec2(234.34, 435.345));
    p += dot(p, p + 34.23);
    return fract(p.x * p.y);
}
float noise2(vec2 p) {
    vec2 i = floor(p), f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash21(i), hash21(i + vec2(1,0)), f.x),
               mix(hash21(i + vec2(0,1)), hash21(i + vec2(1,1)), f.x), f.y);
}
float fbm(vec2 p) {
    float v = 0.0, a = 0.5;
    for (int i = 0; i < 5; i++) {
        v += a * noise2(p);
        p = rot(0.55) * p * 2.08;
        a *= 0.5;
    }
    return v;
}
vec3 aces(vec3 x) {
    return clamp((x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14), 0.0, 1.0);
}

void main() {
    vec2 res = uResolution;
    vec2 uv = (gl_FragCoord.xy - 0.5 * res) / res.y;
    float t = uTime;
    vec2 m = uMouse;
    float breath = uBreath;

    float camElev = 0.32 + m.y * 0.95;
    vec3 ro = vec3(0.0, camElev, -4.6);
    ro.xz *= rot(m.x * 1.8 + t * 0.06);
    vec3 ww = normalize(-ro);
    vec3 up = normalize(vec3(0.18 + m.x * 0.25, 1.0, 0.0));
    vec3 uu = normalize(cross(ww, up));
    vec3 vv = cross(uu, ww);
    vec3 rd = normalize(uv.x * uu + uv.y * vv + 1.45 * ww);

    vec3 col = vec3(0.004, 0.007, 0.014);
    vec3 p = ro, v = rd, accCol = vec3(0.0);
    float dt = 0.045, bhRadius = 0.54, minR = 100.0;
    bool swallowed = false;

    for (int i = 0; i < 135; i++) {
        float r2 = dot(p, p), r = sqrt(r2);
        minR = min(minR, r);
        if (r < bhRadius) { swallowed = true; break; }
        float bend = 0.42 / (r2 * r + 0.008);
        vec3 nextV = normalize(v - p * bend * dt);
        vec3 nextP = p + nextV * dt * clamp(r * 0.65, 0.35, 1.8);

        float diskDist = abs(p.y);
        if (diskDist < 0.16 && r > 0.72 && r < 3.4) {
            float angle = atan(p.z, p.x);
            float radial = (r - 0.72) / (3.4 - 0.72);
            float omega = 1.8 / pow(r, 1.25);
            float clouds = fbm(vec2(r * 5.5, (angle + t * omega) * 3.0 + r * 4.0));
            float fineRings = pow(sin(r * 38.0 - t * 2.5 + clouds * 3.0) * 0.5 + 0.5, 1.6);
            float radialEnv = smoothstep(0.0, 0.08, radial) * pow(1.0 - radial, 1.6);
            float vertEnv = exp(-diskDist * 32.0);
            vec3 velDir = normalize(vec3(-p.z, 0.0, p.x));
            float doppler = clamp(1.0 + 0.65 * dot(velDir, v), 0.25, 2.1);

            vec3 diskCol = mix(vec3(1.0, 0.92, 0.78), vec3(1.0, 0.48, 0.12), smoothstep(0.0, 0.38, radial));
            diskCol = mix(diskCol, vec3(0.55, 0.08, 0.02), smoothstep(0.35, 1.0, radial));
            diskCol = mix(diskCol, vec3(0.35, 0.82, 1.0), clamp((doppler - 1.25) * 0.55, 0.0, 0.65));
            float density = (0.35 + 0.95 * clouds) * (0.55 + 0.45 * fineRings) * radialEnv * vertEnv;
            accCol += diskCol * density * pow(doppler, 2.2) * 0.11;
        }
        float axisDist = length(p.xz), absY = abs(p.y);
        if (absY > 0.55 && absY < 3.8 && axisDist < 0.45) {
            float jetWidth = 0.04 + absY * 0.085;
            float jetMask = exp(-(axisDist * axisDist) / (jetWidth * jetWidth));
            float jetNoise = fbm(vec2(absY * 3.5 - t * 4.5, atan(p.z, p.x) * 2.0));
            float jetFade = smoothstep(0.55, 1.0, absY) * smoothstep(3.8, 1.2, absY);
            accCol += vec3(0.22, 0.72, 1.0) * jetMask * jetNoise * jetFade * (0.018 + 0.008 * breath);
        }
        v = nextV; p = nextP;
        if (r > 8.5 && i > 40) break;
    }
    if (!swallowed) {
        vec2 starUV = v.xy / (abs(v.z) + 0.55) * 34.0;
        vec2 starId = floor(starUV), starF = fract(starUV) - 0.5;
        float starRnd = hash21(starId);
        if (starRnd > 0.93) {
            float starGlow = smoothstep(0.16, 0.0, length(starF)) * (0.65 + 0.35 * sin(t * 2.5 + starRnd * 50.0));
            col += mix(vec3(0.5, 0.8, 1.0), vec3(1.0, 0.85, 0.65), fract(starRnd * 13.0)) * starGlow * 0.7;
        }
        accCol += vec3(1.0, 0.85, 0.6) * exp(-abs(minR - 0.545) * 55.0) * 0.95;
    } else { col = vec3(0.0); }
    col = aces((col + accCol) * 1.15);

    fragColor = vec4(col, 1.0);
}

