}

void main() {
    vec2 res = uResolution;
    vec2 uv = (gl_FragCoord.xy - 0.5 * res) / res.y;
    float t = uTime;
    vec2 m = uMouse;
    float breath = uBreath;

    vec3 ro = vec3(0.0, m.y * 2.0, -4.2);
    ro.xz *= rot(m.x * 2.0 + t * 0.25);
    vec3 ww = normalize(-ro), uu = normalize(cross(ww, vec3(0,1,0))), vv = cross(uu, ww);
    vec3 rd = normalize(uv.x * uu + uv.y * vv + 1.4 * ww);

    vec3 col = vec3(0.003, 0.006, 0.016);
    float tot = 0.0;
    float tilt = 0.45 + 0.15 * sin(t * 0.5);
    for (int i = 0; i < 80; i++) {
        vec3 p = ro + rd * tot;
        p.xz *= rot(t * 2.4);
        p.xy *= rot(tilt);
        float r = length(p);
        // Neutron star core
        float core = r - 0.26;
        // Dipole magnetic field shells: r = L * sin^2(theta)
        float sinTheta2 = dot(p.xz, p.xz) / (r * r + 1e-4);
        float L = r / (sinTheta2 + 0.02);
        float shell = abs(fract(L * 0.55 - t * 0.6) - 0.5) * 0.35;
        float phiLines = abs(sin(atan(p.z, p.x) * 8.0)) * 0.08;
        float dipoleDist = max(shell, phiLines) + max(0.0, r - 2.4);

        // Polar radiation cone along Y axis
        float cone = length(p.xz) - abs(p.y) * 0.22;
        float beamGlow = exp(-max(cone, 0.0) * 14.0) * exp(-abs(p.y) * 0.45) * 0.065;
        float fieldGlow = 0.0035 / (0.012 + dipoleDist * dipoleDist * 6.0) * smoothstep(2.6, 0.35, r);
        float coreGlow = exp(-max(core, 0.0) * 24.0) * 0.09;

        col += vec3(0.15, 0.75, 1.0) * fieldGlow;
        col += vec3(0.65, 0.35, 1.0) * beamGlow * (1.1 + 0.3 * breath);
        col += vec3(0.85, 0.95, 1.0) * coreGlow;
        float stepD = min(max(core, 0.02), max(dipoleDist * 0.4, 0.03));
        tot += stepD;
        if (tot > 7.5) break;
    }
    col = aces(col * 1.25);

    fragColor = vec4(col, 1.0);
}

