    vec3 ww = normalize(-ro), uu = normalize(cross(ww, vec3(0,1,0))), vv = cross(uu, ww);
    vec3 rd = normalize(uv.x * uu + uv.y * vv + 1.3 * ww);

    vec3 col = vec3(0.004, 0.005, 0.012);
    float tot = 1.2;
    for (int i = 0; i < 68; i++) {
        vec3 p = ro + rd * tot;
        float r = length(p);
        if (r < 2.4) {
            vec3 q = p * 1.6;
            q.xy += vec2(fbm(q.yz + t * 0.15), fbm(q.xz - t * 0.12)) * 0.65;
            float n = fbm(q.xy * 1.8 + q.z);
            float shell = exp(-pow((r - 1.25 - 0.12 * breath + n * 0.45) * 3.2, 2.0));
            float filaments = smoothstep(0.42, 0.78, n) * shell;
            vec3 gasCol = mix(vec3(1.0, 0.22, 0.45), vec3(0.12, 0.85, 1.0), smoothstep(0.9, 1.65, r));
            gasCol = mix(gasCol, vec3(1.0, 0.78, 0.25), pow(n, 3.0));
            col += gasCol * filaments * 0.085;
            // Central white dwarf remnant
            col += vec3(0.6, 0.85, 1.0) * exp(-r * 11.0) * 0.04;
        }
        tot += 0.065;
        if (tot > 5.8) break;
    }
    col = aces(col * 1.3);

    fragColor = vec4(col, 1.0);
}

