    vec2 uv = (gl_FragCoord.xy - 0.5 * res) / res.y;
    float t = uTime;
    vec2 m = uMouse;
    float breath = uBreath;

    vec3 ro = vec3(0.0, m.y * 1.2, -3.6);
    ro.xz *= rot(m.x * 1.6 + t * 0.1);
    vec3 ww = normalize(-ro), uu = normalize(cross(ww, vec3(0,1,0))), vv = cross(uu, ww);
    vec3 rd = normalize(uv.x * uu + uv.y * vv + 1.35 * ww);

    float b0 = 0.78; // throat radius
    vec3 p = ro, v = rd;
    float side = 1.0;
    vec3 glowAcc = vec3(0.0);
    for (int i = 0; i < 110; i++) {
        float r = length(p);
        float dr = r - b0;
        if (abs(dr) < 0.06) {
            side = -side; // pass through wormhole throat to parallel universe!
        }
        float force = (b0 * b0) / (r * r * r + 0.04);
        v = normalize(v - (p / (r + 1e-4)) * force * 0.042 * sign(dr));
        p += v * 0.055;
        float throatRing = exp(-abs(dr) * 16.0) * 0.015;
        glowAcc += mix(vec3(0.15, 0.85, 1.0), vec3(1.0, 0.45, 0.15), 0.5 - 0.5 * side) * throatRing;
        if (r > 6.5 && i > 30) break;
    }
    vec2 skyUV = v.xy / (abs(v.z) + 0.5) * 3.5;
    float neb = fbm(skyUV * 1.8 + side * 4.0 + t * 0.08);
    vec3 univA = mix(vec3(0.01, 0.02, 0.05), vec3(0.1, 0.65, 1.0), pow(neb, 2.2));
    vec3 univB = mix(vec3(0.04, 0.01, 0.02), vec3(1.0, 0.38, 0.12), pow(neb, 1.8));
    vec3 col = (side > 0.0 ? univA : univB) + glowAcc;
    float stars = smoothstep(0.95, 1.0, hash21(floor(skyUV * 12.0)));
    col += vec3(0.9, 0.95, 1.0) * stars * 0.6;
    col = aces(col * 1.15);

    fragColor = vec4(col, 1.0);
}

