void main() {
    vec2 res = uResolution;
    vec2 uv = (gl_FragCoord.xy - 0.5 * res) / res.y;
    float t = uTime;
    vec2 m = uMouse;
    float breath = uBreath;

    vec3 ro = vec3(0.0, 0.0, -3.4);
    vec3 rd = normalize(vec3(uv, 1.35));
    float b = dot(ro, rd), c = dot(ro, ro) - 1.15 * 1.15;
    float h = b * b - c;
    vec3 col = vec3(0.008, 0.003, 0.001);

    // Volumetric corona & magnetic prominence arches around limb
    float impact = length(cross(ro, rd));
    float limbDist = max(impact - 1.12, 0.0);
    float angle = atan(uv.y, uv.x) + m.x * 1.5;
    float arch = sin(angle * 7.0 + t * 0.8) * sin(angle * 3.0 - t * 0.5);
    float loopR = 1.15 + max(arch, 0.0) * (0.38 + 0.1 * breath);
    float loopMask = exp(-abs(impact - loopR) * 26.0) * smoothstep(1.12, 1.2, impact);
    float corona = exp(-limbDist * 4.8) * (0.45 + 0.55 * fbm(vec2(angle * 4.0, limbDist * 6.0 - t * 0.9)));
    col += vec3(1.0, 0.35, 0.05) * corona * 0.85;
    col += vec3(1.0, 0.75, 0.25) * loopMask * 1.2;

    if (h > 0.0) {
        float tHit = -b - sqrt(h);
        vec3 pos = ro + rd * tHit;
        vec3 nor = normalize(pos);
        nor.xz *= rot(t * 0.12 + m.x);
        nor.yz *= rot(m.y);
        float gran = fbm(nor.xy * 8.0 + nor.z * 4.0 + t * 0.25);
        float spots = smoothstep(0.28, 0.62, gran);
        float limbDark = pow(clamp(dot(-rd, normalize(pos)), 0.0, 1.0), 0.42);
        vec3 surf = mix(vec3(0.45, 0.06, 0.01), vec3(1.0, 0.45, 0.06), spots);
        surf = mix(surf, vec3(1.0, 0.95, 0.65), pow(gran, 3.2));
        col = surf * limbDark + vec3(1.0, 0.3, 0.04) * pow(1.0 - limbDark, 3.0) * 0.9;
    }
    col = aces(col * 1.1);

    fragColor = vec4(col, 1.0);
}

