    vec2 res = uResolution;
    vec2 uv = (gl_FragCoord.xy - 0.5 * res) / res.y;
    float t = uTime;
    vec2 m = uMouse;
    float breath = uBreath;

    vec3 ro = vec3(0.0, 0.0, -48.0);
    float angY = t * 0.28 + m.x * 2.2, angX = m.y * 1.4;
    vec3 col = vec3(0.004, 0.007, 0.015);

    // Integrate Lorenz ODE trajectories and project to screen
    vec3 p = vec3(0.1, 0.0, 0.0);
    float sigma = 10.0, rho = 28.0, beta = 8.0 / 3.0;
    float dt = 0.0085;
    for (int i = 0; i < 220; i++) {
        vec3 dp = vec3(sigma * (p.y - p.x), p.x * (rho - p.z) - p.y, p.x * p.y - beta * p.z);
        p += dp * dt;
        vec3 q = p - vec3(0.0, 0.0, 25.0);
        q.xz *= rot(angY);
        q.yz *= rot(angX);
        vec2 proj = q.xy / (1.0 + q.z * 0.018) * 0.022;
        float d = length(uv - proj);
        float phase = fract(float(i) / 220.0 - t * 0.35);
        float spark = 0.25 + 0.75 * pow(phase, 3.0);
        vec3 c = mix(vec3(0.1, 0.85, 1.0), vec3(1.0, 0.25, 0.65), float(i) / 220.0);
        col += c * (0.00028 / (d * d + 0.00018)) * spark;
    }
    col = aces(col * 0.95);

    fragColor = vec4(col, 1.0);
}

