    vec3 col = mix(vec3(0.02, 0.005, 0.04), vec3(0.22, 0.02, 0.18), clamp(uv.y + 0.5, 0.0, 1.0));
    // Retro sliced sun
    vec2 sunUV = uv - vec2(m.x * 0.2, 0.14);
    float dSun = length(sunUV);
    if (dSun < 0.22) {
        float slices = step(0.0, sin(sunUV.y * 95.0 - t * 2.0) + sunUV.y * 4.5 + 0.35);
        vec3 sunCol = mix(vec3(1.0, 0.15, 0.55), vec3(1.0, 0.85, 0.2), clamp((sunUV.y + 0.22) / 0.44, 0.0, 1.0));
        col = mix(col, sunCol, slices * smoothstep(0.22, 0.21, dSun));
    }
    // Perspective wireframe terrain below horizon
    if (uv.y < -0.02) {
        float z = 0.25 / abs(uv.y - 0.01);
        float x = (uv.x - m.x * 0.3) * z;
        float elev = pow(abs(x) * 0.35, 1.4) * fbm(vec2(x * 0.8, z * 0.8 + t * 2.2));
        vec2 g = abs(fract(vec2(x, z + t * 2.2) * 1.5) - 0.5);
        float wire = smoothstep(0.06, 0.0, min(g.x, g.y));
        vec3 gridCol = mix(vec3(0.1, 0.9, 1.0), vec3(1.0, 0.2, 0.65), clamp(elev, 0.0, 1.0));
        col = mix(col, gridCol, wire * exp(-z * 0.08));
    }
    col = aces(col * 1.15);

    fragColor = vec4(col, 1.0);
}
